    .task-row { margin: 10px 0; padding: 14px 16px; background: white; border: 1px solid #dce2ea; border-radius: 6px; }
    .task-row input { width: auto; }
    .task-row input[type="checkbox"] {
      display: inline-block;
      visibility: visible;
      opacity: 1;
      width: 18px;
      height: 18px;
      margin: 0 4px 0 0;
      padding: 0;
      flex: 0 0 18px;
      accent-color: #2459a6;
    }
    .filter { margin: 24px 0; }
    .alert { color: #a32323; margin: 12px 0; }
