  </style>
</head>
<body>
  <main id="app"></main>
  <script type="module">
    const app = document.querySelector('#app');
    const projectViewStates = new Map();
    const requestProjects = async (options) => {
      const response = await fetch('/api/projects', options);
      const data = await response.json();
      if (!response.ok) throw new Error(data.error || 'Request failed');
      return data;
    };
    const requestTasks = async (projectId, options) => {
      const response = await fetch(`/api/projects/${projectId}/tasks`, options);
      const data = await response.json();
      if (!response.ok) throw new Error(data.error || 'Request failed');
      return data;
    };
    const requestTaskUpdate = async (projectId, taskId, completed) => {
      const response = await fetch(`/api/projects/${projectId}/tasks/${taskId}`, {
        method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ completed })
      });
      const data = await response.json();
      if (!response.ok) throw new Error(data.error || 'Request failed');
      return data;
    };
    const requestTaskRename = async (projectId, taskId, title) => {
      const response = await fetch(`/api/projects/${projectId}/tasks/${taskId}`, {
        method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ title })
      });
      const data = await response.json();
      if (!response.ok) throw new Error(data.error || 'Request failed');
      return data;
    };
    const requestTaskPriority = async (projectId, taskId, priority) => {
      const response = await fetch(`/api/projects/${projectId}/tasks/${taskId}`, {
        method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ priority })
      });
      const data = await response.json();
      if (!response.ok) throw new Error(data.error || 'Request failed');
      return data;
    };
    const requestTaskDueDate = async (projectId, taskId, due_date) => {
      const response = await fetch(`/api/projects/${projectId}/tasks/${taskId}`, {
        method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ due_date })
      });
      const data = await response.json();
      if (!response.ok) throw new Error(data.error || 'Request failed');
      return data;
    };
    const requestTaskMove = async (projectId, taskId, destination_project_id) => {
      const response = await fetch(`/api/projects/${projectId}/tasks/${taskId}`, {
        method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ destination_project_id })
      });
      const data = await response.json();
      if (!response.ok) throw new Error(data.error || 'Request failed');
      return data;
    };
    const requestProjectArchive = async (projectId, archived) => {
      const response = await fetch(`/api/projects/${projectId}`, {
        method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ archived })
      });
      const data = await response.json();
      if (!response.ok) throw new Error(data.error || 'Request failed');
      return data;
    };
    const requestProjectRename = async (projectId, name) => {
      const response = await fetch(`/api/projects/${projectId}`, {
        method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ name })
      });
      const data = await response.json();
      if (!response.ok) throw new Error(data.error || 'Request failed');
      return data;
    };
    const requestProjectDefaultPriority = async (projectId, priority) => {
      const response = await fetch(`/api/projects/${projectId}`, {
        method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ default_task_priority: priority })
      });
      const data = await response.json();
      if (!response.ok) throw new Error(data.error || 'Request failed');
      return data;
    };

    function renderList(projects, selectedFilter = 'Active') {
      app.replaceChildren();
      const heading = document.createElement('h1');
      heading.textContent = 'Workboard';
      app.append(heading);
      const form = document.createElement('form');
      const field = document.createElement('div');
      const label = document.createElement('label');
      label.htmlFor = 'project-name';
      label.textContent = 'Project name';
      const input = document.createElement('input');
      input.id = 'project-name';
      input.name = 'name';
      input.type = 'text';
      field.append(label, input);
      const submit = document.createElement('button');
      submit.type = 'submit';
      submit.textContent = 'Create project';
      form.append(field, submit);
      const alert = document.createElement('p');
      alert.className = 'alert';
      alert.setAttribute('role', 'alert');
      alert.hidden = true;
      form.addEventListener('submit', async (event) => {
        event.preventDefault();
        try {
          await requestProjects({ method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ name: input.value }) });
          renderList(await requestProjects());
        } catch (error) {
          alert.textContent = error.message;
          alert.hidden = false;
        }
      });
      app.append(form, alert);
      const filterField = document.createElement('div');
      filterField.className = 'filter';
      const filterLabel = document.createElement('label');
      filterLabel.htmlFor = 'project-filter';
      filterLabel.textContent = 'Project filter';
      const filter = document.createElement('select');
      filter.id = 'project-filter';
      for (const value of ['Active', 'Archived']) {
        const option = document.createElement('option');
        option.value = value;
        option.textContent = value;
        option.selected = value === selectedFilter;
        filter.append(option);
      }
      filterField.append(filterLabel, filter);
      app.append(filterField);
      const visibleProjects = projects.filter((project) => project.archived === (filter.value === 'Archived'));
      filter.addEventListener('change', () => renderList(projects, filter.value));
      for (const project of visibleProjects) {
        const row = document.createElement('section');
        row.dataset.testid = 'project-row';
        row.className = 'project-row';
        const name = document.createElement('span');
        name.textContent = project.name;
        const open = document.createElement('button');
        open.type = 'button';
        open.textContent = 'Open project';
        open.addEventListener('click', () => {
          projectViewStates.delete(project.id);
          history.pushState({}, '', `/projects/${project.id}`);
          render();
        });
        const summary = document.createElement('span');
        summary.dataset.testid = 'project-summary';
        summary.textContent = `${project.completed_count}/${project.total_count} completed`;
        const archive = document.createElement('button');
        archive.type = 'button';
        archive.textContent = project.archived ? 'Restore project' : 'Archive project';
        archive.addEventListener('click', async () => {
          try {
            await requestProjectArchive(project.id, !project.archived);
            renderList(await requestProjects(), filter.value);
          } catch (error) {
            alert.textContent = error.message;
            alert.hidden = false;
          }
        });
        row.append(name, summary, open, archive);
        app.append(row);
      }
    }

    async function render() {
      const match = location.pathname.match(/^\/projects\/(\d+)$/);
      if (!match) return renderList(await requestProjects());
      const projects = await requestProjects();
      const project = projects.find((item) => String(item.id) === match[1]);
      app.replaceChildren();
      const back = document.createElement('button');
      back.type = 'button';
      back.className = 'back';
      back.textContent = 'Projects';
      back.addEventListener('click', () => {
        history.pushState({}, '', '/');
        render();
      });
      app.append(back);
      const heading = document.createElement('h1');
      heading.textContent = project ? project.name : 'Project not found';
      app.append(heading);
      if (!project) return;
      const viewState = projectViewStates.get(project.id) || {
        taskFilter: 'All',
        priorityFilter: 'All',
        dueFrom: '',
        dueThrough: '',
        appliedDueFrom: '',
        appliedDueThrough: ''
      };
      projectViewStates.set(project.id, viewState);
      if (project.archived) {
        const archivedNotice = document.createElement('p');
        archivedNotice.textContent = 'Archived project';
        app.append(archivedNotice);
      }

      const alert = document.createElement('p');
      alert.className = 'alert';
      alert.setAttribute('role', 'alert');
      alert.hidden = true;
      app.append(alert);
      const renameForm = document.createElement('form');
      const renameField = document.createElement('div');
      const renameLabel = document.createElement('label');
      renameLabel.htmlFor = 'new-project-name';
      renameLabel.textContent = 'New project name';
      const renameInput = document.createElement('input');
      renameInput.id = 'new-project-name';
      renameInput.name = 'name';
      renameInput.type = 'text';
      renameInput.disabled = project.archived;
      renameField.append(renameLabel, renameInput);
      const renameButton = document.createElement('button');
      renameButton.type = 'submit';
      renameButton.textContent = 'Rename project';
      renameButton.disabled = project.archived;
      renameForm.append(renameField, renameButton);
      renameForm.addEventListener('submit', async (event) => {
        event.preventDefault();
        try {
          await requestProjectRename(project.id, renameInput.value);
          await render();
        } catch (error) {
          alert.textContent = error.message;
          alert.hidden = false;
        }
      });
      app.append(renameForm);
      const defaultPriorityField = document.createElement('div');
      defaultPriorityField.className = 'filter';
      const defaultPriorityLabel = document.createElement('label');
      defaultPriorityLabel.htmlFor = 'default-task-priority';
      defaultPriorityLabel.textContent = 'Default task priority';
      const defaultPriority = document.createElement('select');
      defaultPriority.id = 'default-task-priority';
      defaultPriority.disabled = project.archived;
      for (const value of ['Low', 'Normal', 'High']) {
        const option = document.createElement('option');
        option.value = value;
        option.textContent = value;
        option.selected = value === project.default_task_priority;
        defaultPriority.append(option);
      }
      defaultPriority.addEventListener('change', async () => {
        try {
          await requestProjectDefaultPriority(project.id, defaultPriority.value);
          project.default_task_priority = defaultPriority.value;
          alert.hidden = true;
        } catch (error) {
          defaultPriority.value = project.default_task_priority;
          alert.textContent = error.message;
          alert.hidden = false;
        }
      });
      defaultPriorityField.append(defaultPriorityLabel, defaultPriority);
      app.append(defaultPriorityField);
      const form = document.createElement('form');

      const form = document.createElement('form');
      const field = document.createElement('div');
      const label = document.createElement('label');
      label.htmlFor = 'task-title';
      label.textContent = 'Task title';
      const input = document.createElement('input');
      input.id = 'task-title';
      input.name = 'title';
      input.type = 'text';
      field.append(label, input);
      const submit = document.createElement('button');
      submit.type = 'submit';
      submit.textContent = 'Create task';
      submit.disabled = project.archived;
      form.append(field, submit);
      app.append(form);

      const filterField = document.createElement('div');
      filterField.className = 'filter';
      const filterLabel = document.createElement('label');
      filterLabel.htmlFor = 'task-filter';
      filterLabel.textContent = 'Task filter';
      const filter = document.createElement('select');
      filter.id = 'task-filter';
      for (const value of ['All', 'Open', 'Completed']) {
        const option = document.createElement('option');
        option.value = value;
        option.textContent = value;
        option.selected = value === viewState.taskFilter;
        filter.append(option);
      }
